DROP TABLE IF EXISTS `shift_day_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shift_day_settings` (
  `setting_date` date NOT NULL,
  `morning_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `afternoon_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `evening_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `updated_by` bigint unsigned DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`setting_date`),
  KEY `fk_shift_setting_user` (`updated_by`),
  CONSTRAINT `fk_shift_setting_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
